    """Format a tag for SAM output."""
    if typ in ('c', 'C', 's', 'S', 'i', 'I'):
        return f"{tag}:i:{val}"
    elif typ == 'A':
        return f"{tag}:A:{val}"
    elif typ == 'f':
        # Format float like samtools does
        return f"{tag}:f:{val:g}"
    elif typ == 'Z':
        return f"{tag}:Z:{val}"
    elif typ == 'H':
        return f"{tag}:H:{val}"
    elif typ == 'B':
