#!/usr/bin/env python3
"""
samtools - Python reimplementation of samtools
"""
import sys
import os
import struct
import zlib
import gzip
import hashlib
import math
import re
import io
import copy
from collections import defaultdict

VERSION = "be7a51c"
HTSLIB_VERSION = "1.23.1"

# ============================================================
# BGZF Support
# ============================================================

BGZF_EOF = bytes([
    0x1f, 0x8b, 0x08, 0x04, 0x00, 0x00, 0x00, 0x00, 0x00, 0xff,
    0x06, 0x00, 0x42, 0x43, 0x02, 0x00, 0x1b, 0x00, 0x03, 0x00,
    0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
])

MAX_BGZF_BLOCK = 65536  # max uncompressed block size

def bgzf_create_block(data, level=6):
    """Create a single BGZF block from uncompressed data."""
    assert len(data) <= MAX_BGZF_BLOCK
    compressed = zlib.compress(data, level)[2:-4]  # strip zlib header/trailer
    crc = zlib.crc32(data) & 0xFFFFFFFF
    isize = len(data) & 0xFFFFFFFF
    total = 26 + len(compressed)
    bsize = total - 1
    header = bytes([
        0x1f, 0x8b, 0x08, 0x04, 0x00, 0x00, 0x00, 0x00, 0x00, 0xff,
        6, 0, 0x42, 0x43, 2, 0,
        bsize & 0xFF, (bsize >> 8) & 0xFF
    ])
    trailer = struct.pack('<II', crc, isize)
    return header + compressed + trailer

class BGZFWriter:
    def __init__(self, filename, level=6):
        self.fh = open(filename, 'wb')
        self.level = level
        self.buf = bytearray()
        self.block_start_offset = 0  # for virtual offsets

    def write(self, data):
        if isinstance(data, str):
            data = data.encode()
        self.buf.extend(data)
        while len(self.buf) >= MAX_BGZF_BLOCK:
            self._flush_block(self.buf[:MAX_BGZF_BLOCK])
            self.buf = self.buf[MAX_BGZF_BLOCK:]

    def _flush_block(self, data):
        block = bgzf_create_block(bytes(data), self.level)
        self.fh.write(block)
        self.block_start_offset += len(block)

    def flush(self):
        if self.buf:
            self._flush_block(bytes(self.buf))
            self.buf = bytearray()

    def close(self):
        self.flush()
        self.fh.write(BGZF_EOF)
        self.fh.close()

    def tell_virtual(self):
        """Return virtual offset (current block offset << 16 | uncompressed offset)"""
        return (self.block_start_offset << 16) | len(self.buf)

class BGZFReader:
    """Read BGZF files, tracking virtual offsets."""
    def __init__(self, filename):
        self.fh = open(filename, 'rb')
        self.buf = b''
        self.buf_offset = 0
        self.block_offset = 0  # file offset of current block start
        self.block_uoffset = 0  # uncompressed offset within block
        self._eof = False
        self._read_block()

    def _read_block(self):
        """Read next BGZF block."""
        self.block_offset = self.fh.tell()
        header = self.fh.read(18)
        if len(header) < 18:
            self._eof = True
            self.buf = b''
            return
        if header[0] != 0x1f or header[1] != 0x8b:
            self._eof = True
            self.buf = b''
            return
        xlen = struct.unpack('<H', header[10:12])[0]
        extra = self.fh.read(xlen)
        # Find BSIZE
        bsize = None
        i = 0
        while i + 3 < len(extra):
            if extra[i] == 0x42 and extra[i+1] == 0x43:
                slen = struct.unpack('<H', extra[i+2:i+4])[0]
                bsize = struct.unpack('<H', extra[i+4:i+6])[0]
                break
            i += 1
        if bsize is None:
            self._eof = True
            self.buf = b''
            return
        # Read compressed data
        compressed_size = bsize + 1 - 26 - xlen + 6  # adjusted
        # Actually: total_block_size = bsize + 1
        # header consumed: 10 + 2 + xlen = 12 + xlen bytes
        # trailer: 8 bytes
        # compressed: total - (12 + xlen) - 8 = bsize + 1 - 20 - xlen
        total_block_size = bsize + 1
        compressed_size = total_block_size - 18 - xlen - 8  # 18=10+2+xlen_field, 8=trailer
        # Wait: 10 (basic header) + 2 (xlen field) + xlen (extra data) + compressed + 8 (trailer)
        # = 12 + xlen + compressed + 8 = 20 + xlen + compressed = total
        compressed_size = total_block_size - 20 - xlen
        compressed = self.fh.read(compressed_size)
        crc32 = struct.unpack('<I', self.fh.read(4))[0]
        isize = struct.unpack('<I', self.fh.read(4))[0]

        if isize == 0 and compressed == b'\x03\x00':
            # EOF block
            self._eof = True
            self.buf = b''
            return

        # Decompress
        data = zlib.decompress(compressed, -15)  # raw deflate
        self.buf = data
        self.block_uoffset = 0

    def tell_virtual(self):
        return (self.block_offset << 16) | self.block_uoffset

    def read(self, n):
        result = bytearray()
        while n > 0:
            available = len(self.buf) - self.block_uoffset
            if available <= 0:
                if self._eof:
                    break
                self._read_block()
                if self._eof:
                    break
                available = len(self.buf) - self.block_uoffset
            take = min(n, available)
            result.extend(self.buf[self.block_uoffset:self.block_uoffset+take])
            self.block_uoffset += take
            n -= take
        return bytes(result)

    def close(self):
        self.fh.close()

# ============================================================
# SAM/BAM Format
# ============================================================

CIGAR_CHARS = "MIDNSHP=X"
SEQ_CHARS = "=ACMGRSVTWYHKDBN"

# Cigar operations that consume query/reference
CIGAR_CONSUME_QUERY = {0, 1, 4, 7, 8}  # M,I,S,=,X
CIGAR_CONSUME_REF   = {0, 2, 3, 7, 8}  # M,D,N,=,X

FLAG_PAIRED        = 0x1
FLAG_PROPER_PAIR   = 0x2
FLAG_UNMAP         = 0x4
FLAG_MUNMAP        = 0x8
FLAG_REVERSE       = 0x10
FLAG_MREVERSE      = 0x20
FLAG_READ1         = 0x40
FLAG_READ2         = 0x80
FLAG_SECONDARY     = 0x100
FLAG_QCFAIL        = 0x200
FLAG_DUP           = 0x400
FLAG_SUPPLEMENTARY = 0x800

class BAMRecord:
    __slots__ = ['refID', 'pos', 'mapq', 'bin', 'n_cigar_op', 'flag', 
                 'l_seq', 'next_refID', 'next_pos', 'tlen',
                 'read_name', 'cigar', 'seq', 'qual', 'tags_raw',
                 '_tags_parsed']

    def __init__(self):
        self.refID = -1
        self.pos = -1
        self.mapq = 255
        self.bin = 0
        self.n_cigar_op = 0
        self.flag = 0
        self.l_seq = 0
        self.next_refID = -1
        self.next_pos = -1
        self.tlen = 0
        self.read_name = '*'
        self.cigar = []  # list of (op_len, op_code)
        self.seq = ''
        self.qual = b''
        self.tags_raw = b''
        self._tags_parsed = None

    def get_tags(self):
        if self._tags_parsed is None:
            self._tags_parsed = parse_bam_tags(self.tags_raw)
        return self._tags_parsed

    def cigar_str(self):
        if not self.cigar:
            return '*'
        return ''.join(f"{l}{CIGAR_CHARS[op]}" for l, op in self.cigar)

    def qual_str(self):
        if not self.qual or self.qual == b'\xff' * len(self.qual):
            return '*'
        return ''.join(chr(q + 33) for q in self.qual)

    def tags_str(self):
        tags = self.get_tags()
        parts = []
        for tag, typ, val in tags:
            parts.append(format_sam_tag(tag, typ, val))
        return '\t'.join(parts)

    def to_sam_line(self, refs):
        rname = refs[self.refID][0] if self.refID >= 0 else '*'
        if self.pos >= 0:
            pos1 = self.pos + 1
        else:
            pos1 = 0

        if self.next_refID == self.refID and self.next_refID >= 0:
            rnext = '='
        elif self.next_refID >= 0:
            rnext = refs[self.next_refID][0]
        else:
            rnext = '*'

        if self.next_pos >= 0:
            pnext = self.next_pos + 1
        else:
            pnext = 0

        tags = self.tags_str()
        parts = [
            self.read_name,
            str(self.flag),
            rname,
            str(pos1),
            str(self.mapq),
            self.cigar_str(),
            rnext,
            str(pnext),
            str(self.tlen),
            self.seq if self.seq else '*',
            self.qual_str(),
        ]
        if tags:
            parts.append(tags)
        return '\t'.join(parts)

    def query_len(self):
        """Length of query sequence based on CIGAR"""
        return sum(l for l, op in self.cigar if op in CIGAR_CONSUME_QUERY)

    def ref_len(self):
        """Length consumed on reference based on CIGAR"""
        return sum(l for l, op in self.cigar if op in CIGAR_CONSUME_REF)

def parse_bam_tags(data):
    """Parse BAM tag binary data into list of (tag, type, value)."""
    tags = []
    i = 0
    while i < len(data):
        if i + 2 > len(data):
            break
        tag = data[i:i+2].decode('latin-1')
        i += 2
        if i >= len(data):
            break
        val_type = chr(data[i])
        i += 1
        if val_type == 'A':
            val = chr(data[i]); i += 1
        elif val_type == 'c':
            val = struct.unpack_from('<b', data, i)[0]; i += 1
        elif val_type == 'C':
            val = struct.unpack_from('<B', data, i)[0]; i += 1
        elif val_type == 's':
            val = struct.unpack_from('<h', data, i)[0]; i += 2
        elif val_type == 'S':
            val = struct.unpack_from('<H', data, i)[0]; i += 2
        elif val_type == 'i':
            val = struct.unpack_from('<i', data, i)[0]; i += 4
        elif val_type == 'I':
            val = struct.unpack_from('<I', data, i)[0]; i += 4
        elif val_type == 'f':
            val = struct.unpack_from('<f', data, i)[0]; i += 4
        elif val_type == 'Z':
            end = data.index(0, i)
            val = data[i:end].decode('latin-1'); i = end + 1
        elif val_type == 'H':
            end = data.index(0, i)
            val = data[i:end].decode('latin-1'); i = end + 1
        elif val_type == 'B':
            sub_type = chr(data[i]); i += 1
            count = struct.unpack_from('<I', data, i)[0]; i += 4
            type_map = {'c':('b',1), 'C':('B',1), 's':('h',2), 'S':('H',2),
                       'i':('i',4), 'I':('I',4), 'f':('f',4)}
            fmt_char, sz = type_map[sub_type]
            val = (sub_type, list(struct.unpack_from(f'<{count}{fmt_char}', data, i)))
            i += count * sz
        else:
            break
        tags.append((tag, val_type, val))
    return tags

def format_sam_tag(tag, typ, val):
    """Format a tag for SAM output."""
    if typ in ('c', 'C', 's', 'S', 'i', 'I'):
        return f"{tag}:i:{val}"
    elif typ == 'A':
        return f"{tag}:A:{val}"
    elif typ == 'f':
        # Format float like samtools does
        return f"{tag}:f:{val:g}"
    elif typ == 'Z':
        return f"{tag}:Z:{val}"
    elif typ == 'H':
        return f"{tag}:H:{val}"
    elif typ == 'B':
        sub_type, values = val
        if sub_type == 'f':
            vals_str = ','.join(f"{v:g}" for v in values)
        else:
            vals_str = ','.join(str(v) for v in values)
        return f"{tag}:B:{sub_type},{vals_str}"
    return f"{tag}:{typ}:{val}"

def encode_bam_tag(tag, typ, val):
    """Encode a tag in BAM binary format."""
    result = tag.encode('latin-1')
    if typ in ('c', 'C', 's', 'S', 'i', 'I'):
        # Determine best integer type
        ival = int(val)
        if 0 <= ival <= 255:
            result += b'C' + struct.pack('<B', ival)
        elif -128 <= ival <= 127:
            result += b'c' + struct.pack('<b', ival)
        elif 0 <= ival <= 65535:
            result += b'S' + struct.pack('<H', ival)
        elif -32768 <= ival <= 32767:
            result += b's' + struct.pack('<h', ival)
        elif 0 <= ival <= 4294967295:
            result += b'I' + struct.pack('<I', ival)
        else:
            result += b'i' + struct.pack('<i', ival)
    elif typ == 'A':
        result += b'A' + val.encode('latin-1')
    elif typ == 'f':
        result += b'f' + struct.pack('<f', float(val))
    elif typ == 'Z':
        result += b'Z' + val.encode('latin-1') + b'\x00'
    elif typ == 'H':
        result += b'H' + val.encode('latin-1') + b'\x00'
    elif typ == 'B':
        sub_type, values = val
        result += b'B' + sub_type.encode()
        result += struct.pack('<I', len(values))
        type_map = {'c':'b', 'C':'B', 's':'h', 'S':'H', 'i':'i', 'I':'I', 'f':'f'}
        fmt = type_map[sub_type]
        for v in values:
            result += struct.pack(f'<{fmt}', v)
    return result

def encode_bam_tag_preserve(tag, orig_type, val):
    """Encode a tag preserving original type."""
    result = tag.encode('latin-1')
    if orig_type == 'c':
        result += b'c' + struct.pack('<b', int(val))
    elif orig_type == 'C':
        result += b'C' + struct.pack('<B', int(val))
    elif orig_type == 's':
        result += b's' + struct.pack('<h', int(val))
    elif orig_type == 'S':
        result += b'S' + struct.pack('<H', int(val))
    elif orig_type == 'i':
        result += b'i' + struct.pack('<i', int(val))
    elif orig_type == 'I':
        result += b'I' + struct.pack('<I', int(val))
    elif orig_type == 'A':
        result += b'A' + val.encode('latin-1')
    elif orig_type == 'f':
        result += b'f' + struct.pack('<f', float(val))
    elif orig_type == 'Z':
        result += b'Z' + str(val).encode('latin-1') + b'\x00'
    elif orig_type == 'H':
        result += b'H' + str(val).encode('latin-1') + b'\x00'
    elif orig_type == 'B':
        sub_type, values = val
        result += b'B' + sub_type.encode()
        result += struct.pack('<I', len(values))
        type_map = {'c':'b', 'C':'B', 's':'h', 'S':'H', 'i':'i', 'I':'I', 'f':'f'}
        fmt = type_map[sub_type]
        for v in values:
            result += struct.pack(f'<{fmt}', v)
    return result

def reg2bin(beg, end):
    """Calculate the bin given alignment [beg,end) (zero-based, half-open interval)"""
    end -= 1
    if beg >> 14 == end >> 14: return ((1 << 15) - 1) // 7 + (beg >> 14)
    if beg >> 17 == end >> 17: return ((1 << 12) - 1) // 7 + (beg >> 17)
    if beg >> 20 == end >> 20: return ((1 << 9) - 1) // 7 + (beg >> 20)
    if beg >> 23 == end >> 23: return ((1 << 6) - 1) // 7 + (beg >> 23)
    if beg >> 26 == end >> 26: return ((1 << 3) - 1) // 7 + (beg >> 26)
    return 0

def reg2bins(beg, end):
    """Return list of bins that overlap [beg,end)"""
    bins = [0]
    k = 1 + (beg >> 26)
    bins.extend(range(k, 1 + ((end-1) >> 26) + 1))
    k = 9 + (beg >> 23)
    bins.extend(range(k, 9 + ((end-1) >> 23) + 1))
    k = 73 + (beg >> 20)
    bins.extend(range(k, 73 + ((end-1) >> 20) + 1))
    k = 585 + (beg >> 17)
    bins.extend(range(k, 585 + ((end-1) >> 17) + 1))
    k = 4681 + (beg >> 14)
    bins.extend(range(k, 4681 + ((end-1) >> 14) + 1))
    return bins

def encode_seq(seq):
    """Encode sequence to 4-bit BAM format."""
    seq_map = {c: i for i, c in enumerate(SEQ_CHARS)}
    seq = seq.upper()
    nbytes = (len(seq) + 1) // 2
    result = bytearray(nbytes)
    for i, c in enumerate(seq):
        nib = seq_map.get(c, 15)
        if i % 2 == 0:
            result[i // 2] = nib << 4
        else:
            result[i // 2] |= nib
    return bytes(result)

def decode_seq(data, length):
    """Decode 4-bit encoded sequence."""
    result = []
    for i in range(length):
        byte = data[i // 2]
        if i % 2 == 0:
            nib = (byte >> 4) & 0xF
        else:
            nib = byte & 0xF
        result.append(SEQ_CHARS[nib])
    return ''.join(result)

class BAMFile:
    """Read a BAM file."""
    def __init__(self, filename):
        self.filename = filename
        if filename == '-':
            self.fh = gzip.open(sys.stdin.buffer, 'rb')
        elif filename.endswith('.bam'):
            self.fh = gzip.open(filename, 'rb')
        else:
            self.fh = open(filename, 'rt')

        self.refs = []  # list of (name, length)
        self.header_text = ''
        self.is_bam = filename.endswith('.bam') or filename == '-'

        if self.is_bam:
            self._read_bam_header()
        else:
            self._read_sam_header()

    def _read_bam_header(self):
        magic = self.fh.read(4)
        if magic != b'BAM\x01':
            raise ValueError(f"Not a BAM file: {self.filename}")
        l_text = struct.unpack('<i', self.fh.read(4))[0]
        self.header_text = self.fh.read(l_text).decode('latin-1')
        n_ref = struct.unpack('<i', self.fh.read(4))[0]
        for i in range(n_ref):
            l_name = struct.unpack('<i', self.fh.read(4))[0]
            name = self.fh.read(l_name)[:-1].decode('latin-1')
            l_ref = struct.unpack('<i', self.fh.read(4))[0]
            self.refs.append((name, l_ref))

    def _read_sam_header(self):
        # Read SAM header lines
        self._sam_lines = []
        self._sam_buffer = []
        while True:
            line = self.fh.readline()
            if not line:
                break
            line = line.rstrip('\n')
            if line.startswith('@'):
                self.header_text += line + '\n'
                self._parse_sam_header_line(line)
            else:
                self._sam_buffer.append(line)
                break

    def _parse_sam_header_line(self, line):
        if line.startswith('@SQ'):
            fields = dict(f.split(':', 1) for f in line.split('\t')[1:] if ':' in f)
            name = fields.get('SN', '')
            length = int(fields.get('LN', 0))
            self.refs.append((name, length))

    def records(self):
        if self.is_bam:
            yield from self._bam_records()
        else:
            yield from self._sam_records()

    def _bam_records(self):
        while True:
            block_size_data = self.fh.read(4)
            if len(block_size_data) < 4:
                break
            block_size = struct.unpack('<i', block_size_data)[0]
            data = self.fh.read(block_size)
            if len(data) < block_size:
                break
            rec = self._parse_bam_record(data)
            yield rec

    def _parse_bam_record(self, data):
        rec = BAMRecord()
        offset = 0
        rec.refID = struct.unpack_from('<i', data, offset)[0]; offset += 4
        rec.pos = struct.unpack_from('<i', data, offset)[0]; offset += 4
        l_read_name = struct.unpack_from('<B', data, offset)[0]; offset += 1
        rec.mapq = struct.unpack_from('<B', data, offset)[0]; offset += 1
        rec.bin = struct.unpack_from('<H', data, offset)[0]; offset += 2
        n_cigar_op = struct.unpack_from('<H', data, offset)[0]; offset += 2
        rec.flag = struct.unpack_from('<H', data, offset)[0]; offset += 2
        l_seq = struct.unpack_from('<I', data, offset)[0]; offset += 4
        rec.next_refID = struct.unpack_from('<i', data, offset)[0]; offset += 4
        rec.next_pos = struct.unpack_from('<i', data, offset)[0]; offset += 4
        rec.tlen = struct.unpack_from('<i', data, offset)[0]; offset += 4
        rec.l_seq = l_seq

        rec.read_name = data[offset:offset+l_read_name-1].decode('latin-1')
        offset += l_read_name

        rec.cigar = []
        for i in range(n_cigar_op):
            cigar_int = struct.unpack_from('<I', data, offset)[0]; offset += 4
            op_len = cigar_int >> 4
            op_code = cigar_int & 0xF
            rec.cigar.append((op_len, op_code))

        seq_bytes = (l_seq + 1) // 2
        if l_seq > 0:
            rec.seq = decode_seq(data[offset:offset+seq_bytes], l_seq)
        else:
            rec.seq = ''
        offset += seq_bytes

        if l_seq > 0:
            qual_data = data[offset:offset+l_seq]
            if qual_data and qual_data[0] == 0xff:
                rec.qual = b''
            else:
                rec.qual = qual_data
        else:
            rec.qual = b''
        offset += l_seq

        rec.tags_raw = data[offset:]
        return rec

    def _sam_records(self):
        for line in self._sam_buffer:
            if line and not line.startswith('@'):
                rec = self._parse_sam_line(line)
                if rec:
                    yield rec
        for line in self.fh:
            line = line.rstrip('\n')
            if line and not line.startswith('@'):
                rec = self._parse_sam_line(line)
                if rec:
                    yield rec

    def _parse_sam_line(self, line):
        fields = line.split('\t')
        if len(fields) < 11:
            return None
        rec = BAMRecord()
        rec.read_name = fields[0]
        rec.flag = int(fields[1])
        rname = fields[2]
        rec.refID = self._ref_idx(rname)
        pos = int(fields[3])
        rec.pos = pos - 1 if pos > 0 else -1
        rec.mapq = int(fields[4])
        cigar_str = fields[5]
        rec.cigar = parse_cigar(cigar_str)
        rnext = fields[6]
        if rnext == '=':
            rec.next_refID = rec.refID
        elif rnext == '*':
            rec.next_refID = -1
        else:
            rec.next_refID = self._ref_idx(rnext)
        pnext = int(fields[7])
        rec.next_pos = pnext - 1 if pnext > 0 else -1
        rec.tlen = int(fields[8])
        rec.seq = fields[9] if fields[9] != '*' else ''
        rec.l_seq = len(rec.seq)
        qual_str = fields[10]
        if qual_str == '*':
            rec.qual = b''
        else:
            rec.qual = bytes(ord(c) - 33 for c in qual_str)

        # Parse tags
        tags = []
        for tag_str in fields[11:]:
            t = parse_sam_tag_str(tag_str)
            if t:
                tags.append(t)
        rec._tags_parsed = tags
        rec.tags_raw = encode_tags_to_bam(tags)

        # Calculate bin
        if rec.pos >= 0 and rec.cigar:
            end = rec.pos + rec.ref_len()
            rec.bin = reg2bin(rec.pos, end)
        elif rec.pos >= 0:
            rec.bin = reg2bin(rec.pos, rec.pos + 1)

        return rec

    def _ref_idx(self, name):
        if name == '*':
            return -1
        for i, (n, l) in enumerate(self.refs):
            if n == name:
                return i
        return -1

    def close(self):
        self.fh.close()

def parse_cigar(cigar_str):
    """Parse CIGAR string to list of (length, op_code) tuples."""
    if cigar_str == '*':
        return []
    result = []
    for m in re.finditer(r'(\d+)([MIDNSHP=X])', cigar_str):
        length = int(m.group(1))
        op_char = m.group(2)
        op_code = CIGAR_CHARS.index(op_char)
        result.append((length, op_code))
    return result

def parse_sam_tag_str(tag_str):
    """Parse a SAM tag string like 'NM:i:5' into (tag, type, value)."""
    parts = tag_str.split(':', 2)
    if len(parts) != 3:
        return None
    tag, typ, val = parts
    if typ == 'i':
        return (tag, typ, int(val))
    elif typ == 'f':
        return (tag, typ, float(val))
    elif typ == 'A':
        return (tag, typ, val)
    elif typ == 'Z':
        return (tag, typ, val)
    elif typ == 'H':
        return (tag, typ, val)
    elif typ == 'B':
        sub_type = val[0]
        values_str = val[2:].split(',') if len(val) > 1 else []
        if sub_type == 'f':
            values = [float(v) for v in values_str]
        else:
            values = [int(v) for v in values_str]
        return (tag, typ, (sub_type, values))
    return (tag, typ, val)

def encode_tags_to_bam(tags):
    """Encode list of (tag, type, value) tuples to BAM binary."""
    result = b''
    for tag, typ, val in tags:
        result += encode_bam_tag(tag, typ, val)
    return result

def encode_record_to_bam(rec):
    """Encode a BAMRecord to BAM binary format."""
    read_name_bytes = rec.read_name.encode('latin-1') + b'\x00'
    l_read_name = len(read_name_bytes)

    cigar_bytes = b''
    for op_len, op_code in rec.cigar:
        cigar_bytes += struct.pack('<I', (op_len << 4) | op_code)

    seq_str = rec.seq if rec.seq else ''
    l_seq = len(seq_str)
    seq_bytes = encode_seq(seq_str) if seq_str else b''

    if rec.qual:
        qual_bytes = bytes(rec.qual)
    elif l_seq > 0:
        qual_bytes = bytes([0xff] * l_seq)
    else:
        qual_bytes = b''

    # Get tags - use raw if available and parsed is None
    if rec._tags_parsed is not None:
        tags_bytes = b''
        for tag, typ, val in rec._tags_parsed:
            tags_bytes += encode_bam_tag(tag, typ, val)
    else:
        tags_bytes = rec.tags_raw

    # Calculate bin if not set
    bin_val = rec.bin
    if bin_val == 0 and rec.pos >= 0 and rec.cigar:
        end = rec.pos + rec.ref_len()
        bin_val = reg2bin(rec.pos, max(end, rec.pos + 1))

    core = struct.pack('<iiBBHHHIiii',
        rec.refID, rec.pos,
        l_read_name, rec.mapq, bin_val,
        len(rec.cigar), rec.flag, l_seq,
        rec.next_refID, rec.next_pos, rec.tlen)

    data = core + read_name_bytes + cigar_bytes + seq_bytes + qual_bytes + tags_bytes
    return struct.pack('<i', len(data)) + data

def write_bam_header(writer, header_text, refs):
    """Write BAM header to BGZF writer."""
    header_bytes = header_text.encode('latin-1')
    core = struct.pack('<4si', b'BAM\x01', len(header_bytes))
    core += header_bytes
    core += struct.pack('<i', len(refs))
    for name, length in refs:
        name_bytes = name.encode('latin-1') + b'\x00'
        core += struct.pack('<i', len(name_bytes))
        core += name_bytes
        core += struct.pack('<i', length)
    writer.write(core)

def write_sam_header(fh, header_text):
    """Write SAM header."""
    fh.write(header_text)

