def add_pg_line(header_text, cmd_line, prog_id="samtools"):
    """Add a @PG line to the header."""
    # Find existing PG lines to determine ID and PP
    pg_ids = []
    last_pg_id = None
    for line in header_text.split('\n'):
        if line.startswith('@PG'):
            fields = dict(f.split(':', 1) for f in line.split('\t')[1:] if ':' in f)
            pg_id = fields.get('ID', '')
            pg_ids.append(pg_id)
            last_pg_id = pg_id

    # Determine new ID
    new_id = prog_id
    counter = 1
    while new_id in pg_ids:
        new_id = f"{prog_id}.{counter}"
        counter += 1

    pg_line = f"@PG\tID:{new_id}\tPN:{prog_id}\t"
    if last_pg_id:
        pg_line += f"PP:{last_pg_id}\t"
    pg_line += f"VN:{VERSION}\tCL:{cmd_line}"

    # Add to header
    if header_text.endswith('\n'):
        return header_text + pg_line + '\n'
    else:
        return header_text + '\n' + pg_line + '\n'

def parse_region(region):
    """Parse a region string like 'chr1:1000-2000'."""
    if ':' in region:
        name, coords = region.rsplit(':', 1)
        if '-' in coords:
            s, e = coords.split('-', 1)
            return name, int(s) - 1, int(e)  # 0-based half-open
        else:
            pos = int(coords) - 1
            return name, pos, pos + 1
    return region, 0, 2**31 - 1

def record_overlaps_region(rec, refID, beg, end):
    """Check if a record overlaps the given region."""
    if rec.refID != refID:
        return False
    if rec.pos < 0:
        return False
    rec_end = rec.pos + max(rec.ref_len(), 1)
    return rec.pos < end and rec_end > beg

