def cmd_idxstats(args):
    """samtools idxstats - BAM index stats."""
    if not args:
        print("Usage: samtools idxstats <in.bam>", file=sys.stderr)
        return 1

    bam_file = args[0]
    bai_file = bam_file + '.bai'

    if not os.path.exists(bai_file):
        print(f"[bam_index_load] fail to load BAM index {bai_file}", file=sys.stderr)
        return 1

    bf = BAMFile(bam_file)
    refs = bf.refs
    bf.close()

    # Read BAI for chunk info
    mapped = [0] * len(refs)
    unmapped = [0] * len(refs)
    no_coor = 0

    with open(bai_file, 'rb') as f:
        magic = f.read(4)
        n_ref = struct.unpack('<i', f.read(4))[0]
        for r in range(n_ref):
            n_bin = struct.unpack('<i', f.read(4))[0]
            ref_mapped = 0
            ref_unmapped = 0
            for b in range(n_bin):
                bin_ = struct.unpack('<I', f.read(4))[0]
                n_chunk = struct.unpack('<i', f.read(4))[0]
                for c in range(n_chunk):
                    beg = struct.unpack('<Q', f.read(8))[0]
                    end = struct.unpack('<Q', f.read(8))[0]
                    if bin_ == 37450:
                        # Pseudo-bin: last two chunks are mapped/unmapped counts
                        if c == 1:
                            ref_mapped = beg
                            ref_unmapped = end

            if r < len(mapped):
                mapped[r] = ref_mapped
                unmapped[r] = ref_unmapped

            n_intv = struct.unpack('<i', f.read(4))[0]
            f.read(n_intv * 8)

        remaining = f.read(8)
        if len(remaining) == 8:
            no_coor = struct.unpack('<Q', remaining)[0]

    for i, (name, length) in enumerate(refs):
        print(f"{name}\t{length}\t{mapped[i]}\t{unmapped[i]}")
    print(f"*\t0\t0\t{no_coor}")

    return 0

