def cmd_depth(args):
    """samtools depth - compute the depth."""
    all_positions = False
    bam_files = []
    max_depth = 8000
    region = None
    min_mapq = 0
    min_bq = 0
    output_file = None
    bed_file = None

    i = 0
    while i < len(args):
        a = args[i]
        if a == '-a':
            all_positions = True
        elif a == '-aa':
            all_positions = True
        elif a == '-d':
            i += 1
            if i < len(args):
                max_depth = int(args[i])
        elif a == '-r':
            i += 1
            if i < len(args):
                region = args[i]
        elif a in ('-q', '--min-BQ'):
            i += 1
            if i < len(args):
                min_bq = int(args[i])
        elif a in ('-Q', '--min-MQ'):
            i += 1
            if i < len(args):
                min_mapq = int(args[i])
        elif a in ('-o', '--output'):
            i += 1
            if i < len(args):
                output_file = args[i]
        elif a in ('-b', '--bed'):
            i += 1
            if i < len(args):
                bed_file = args[i]
        elif a in ('-@', '--threads'):
            i += 1
        elif not a.startswith('-'):
            bam_files.append(a)
        i += 1

    if not bam_files:
        print("Usage: samtools depth [options] <in1.bam> [<in2.bam> [... <inN.bam>]]", file=sys.stderr)
        return 1

    out = open(output_file, 'w') if output_file else sys.stdout

    for bam_file in bam_files:
        bf = BAMFile(bam_file)
        refs = bf.refs

        # Build depth array for each reference
        # depth[refID][pos] = count
        ref_depths = {}

        for rec in bf.records():
            if rec.flag & FLAG_UNMAP:
                continue
            if rec.flag & FLAG_SECONDARY:
                continue
            if rec.flag & FLAG_SUPPLEMENTARY:
                continue
            if rec.mapq < min_mapq:
                continue
            if rec.refID < 0 or rec.pos < 0:
                continue

            if rec.refID not in ref_depths:
                ref_depths[rec.refID] = defaultdict(int)

            # Walk through CIGAR to determine coverage
            pos = rec.pos
            qi = 0  # query index
            qual = rec.qual

            for op_len, op_code in rec.cigar:
                if op_code in (0, 7, 8):  # M, =, X
                    for j in range(op_len):
                        if min_bq > 0 and qual and qi < len(qual) and qual[qi] < min_bq:
                            pass
                        else:
                            ref_depths[rec.refID][pos + j] += 1
                        qi += 1
                    pos += op_len
                elif op_code == 2:  # D
                    pos += op_len
                elif op_code == 3:  # N
                    pos += op_len
                elif op_code == 1:  # I
                    qi += op_len
                elif op_code == 4:  # S
                    qi += op_len
                elif op_code == 5:  # H
                    pass

        bf.close()

        if region:
            rname, beg, end = parse_region(region)
            ref_idx = -1
            for i, (n, l) in enumerate(refs):
                if n == rname:
                    ref_idx = i
                    break
            if ref_idx < 0:
                continue

            depths = ref_depths.get(ref_idx, {})
            if all_positions:
                rlen = refs[ref_idx][1]
                for pos in range(beg, min(end, rlen)):
                    d = depths.get(pos, 0)
                    out.write(f"{rname}\t{pos+1}\t{d}\n")
            else:
                for pos in sorted(depths.keys()):
                    if beg <= pos < end:
                        out.write(f"{rname}\t{pos+1}\t{depths[pos]}\n")
        else:
            for r_idx, (rname, rlen) in enumerate(refs):
                depths = ref_depths.get(r_idx, {})
                if all_positions:
                    for pos in range(rlen):
                        d = depths.get(pos, 0)
                        out.write(f"{rname}\t{pos+1}\t{d}\n")
                else:
                    for pos in sorted(depths.keys()):
                        out.write(f"{rname}\t{pos+1}\t{depths[pos]}\n")

    if output_file:
        out.close()

    return 0

