                output_file = args[i]
        elif a == '-l':
            i += 1
            if i < len(args):
                compress_level = int(args[i])
        elif a == '-u':
            compress_level = 0
        elif a == '-t':
            i += 1
            if i < len(args):
                sort_by_tag = args[i]
        elif a == '--no-PG':
            no_pg = True
        elif a in ('-@', '--threads', '-m', '-T', '-K', '-w'):
            i += 1  # skip value
        elif a in ('-M', '-R', '-H'):
            pass  # flags to skip
        elif a in ('-O', '--output-fmt'):
            i += 1
