                bam_file = a
            elif output_file is None and a.endswith('.bam'):
                output_file = a
        i += 1

    if bam_file is None:
        print("Usage: samtools sort [options...] [in.bam]", file=sys.stderr)
        return 1

    bf = BAMFile(bam_file)
    refs = bf.refs
    header_text = bf.header_text

    if not no_pg:
        cmd = ' '.join(['sort'] + args)
        header_text = add_pg_line(header_text, cmd)

    # Read all records
    records = list(bf.records())
    bf.close()

    # Sort
    if sort_by_name_natural or sort_by_name:
        def name_key(rec):
            return rec.read_name
        records.sort(key=name_key)
    elif sort_by_tag:
        def tag_key(rec):
            tags = rec.get_tags()
            for t, ty, v in tags:
                if t == sort_by_tag:
                    return (0, v)
            return (1, 0)
        records.sort(key=tag_key)
    else:
        def coord_key(rec):
            return (rec.refID if rec.refID >= 0 else 0x7fffffff, 
                    rec.pos if rec.pos >= 0 else 0x7fffffff)
        records.sort(key=coord_key)

    # Write output
    if output_file:
        writer = BGZFWriter(output_file, level=compress_level)
        write_bam_header(writer, header_text, refs)
        for rec in records:
            writer.write(encode_record_to_bam(rec))
        writer.close()
    else:
        # Write to stdout
        buf = bytearray()
        # Write header as BGZF
        header_data = bytearray()
        header_bytes = header_text.encode('latin-1')
        header_data.extend(struct.pack('<4si', b'BAM\x01', len(header_bytes)))
        header_data.extend(header_bytes)
        header_data.extend(struct.pack('<i', len(refs)))
        for name, length in refs:
            name_bytes = name.encode('latin-1') + b'\x00'
            header_data.extend(struct.pack('<i', len(name_bytes)))
            header_data.extend(name_bytes)
            header_data.extend(struct.pack('<i', length))

        sys.stdout.buffer.write(bgzf_create_block(bytes(header_data)))
        for rec in records:
            sys.stdout.buffer.write(bgzf_create_block(encode_record_to_bam(rec)))
        sys.stdout.buffer.write(BGZF_EOF)

    return 0

