            if i < len(args):
                output_file = args[i]
        elif a == '--no-PG':
            no_pg = True
        elif a in ('-@', '--threads', '-l', '-s', '-h', '-b', '-R'):
            i += 1
        elif a in ('-n', '-N', '-r', '-u', '-1', '-c', '-p', '-X', '-L', '-M'):
            pass
        elif not a.startswith('-'):
            if output_file is None and not input_files:
                output_file = a
            else:
                input_files.append(a)
        i += 1

    if output_file is None or not input_files:
        print("Usage: samtools merge [options] -o <out.bam> [options] <in1.bam> ... <inN.bam>", file=sys.stderr)
        return 1

    if os.path.exists(output_file) and not force:
        print(f"[merge] {output_file} exists; use -f to overwrite", file=sys.stderr)
        return 1

    # Read first file's header
    first = BAMFile(input_files[0])
    refs = first.refs
    header_text = first.header_text
    first.close()

    if not no_pg:
        cmd = ' '.join(['merge'] + args)
        header_text = add_pg_line(header_text, cmd)

    # Merge all files
    import heapq

    readers = []
    for f in input_files:
        bf = BAMFile(f)
        readers.append(bf)

    # Simple merge: read all records and sort
    all_records = []
    for bf in readers:
        for rec in bf.records():
            all_records.append(rec)
        bf.close()

    all_records.sort(key=lambda r: (r.refID if r.refID >= 0 else 0x7fffffff,
                                     r.pos if r.pos >= 0 else 0x7fffffff))

    writer = BGZFWriter(output_file)
    write_bam_header(writer, header_text, refs)
    for rec in all_records:
        writer.write(encode_record_to_bam(rec))
