# ============================================================
# samtools flags
# ============================================================

FLAG_NAMES = [
    (0x1,    "PAIRED"),
    (0x2,    "PROPER_PAIR"),
    (0x4,    "UNMAP"),
    (0x8,    "MUNMAP"),
    (0x10,   "REVERSE"),
    (0x20,   "MREVERSE"),
    (0x40,   "READ1"),
    (0x80,   "READ2"),
    (0x100,  "SECONDARY"),
    (0x200,  "QCFAIL"),
    (0x400,  "DUP"),
    (0x800,  "SUPPLEMENTARY"),
]

FLAG_NAME_TO_VAL = {name: val for val, name in FLAG_NAMES}

def parse_flag_value(s):
    """Parse a flag value (integer or name list)."""
    s = s.strip()
    # Try as integer
    try:
        if s.startswith('0x') or s.startswith('0X'):
            return int(s, 16)
        elif s.startswith('0') and len(s) > 1:
            return int(s, 8)
        else:
            return int(s)
    except ValueError:
        pass

    # Try as comma-separated names
    total = 0
    for name in s.split(','):
        name = name.strip()
        if name in FLAG_NAME_TO_VAL:
            total |= FLAG_NAME_TO_VAL[name]
        else:
            raise ValueError(f"Unknown flag: {name}")
