FLAG_NAMES = [
    (0x1,    "PAIRED"),
    (0x2,    "PROPER_PAIR"),
    (0x4,    "UNMAP"),
    (0x8,    "MUNMAP"),
    (0x10,   "REVERSE"),
    (0x20,   "MREVERSE"),
    (0x40,   "READ1"),
    (0x80,   "READ2"),
    (0x100,  "SECONDARY"),
    (0x200,  "QCFAIL"),
    (0x400,  "DUP"),
    (0x800,  "SUPPLEMENTARY"),
]

FLAG_NAME_TO_VAL = {name: val for val, name in FLAG_NAMES}

def parse_flag_value(s):
    """Parse a flag value (integer or name list)."""
    s = s.strip()
    # Try as integer
    try:
        if s.startswith('0x') or s.startswith('0X'):
            return int(s, 16)
        elif s.startswith('0') and len(s) > 1:
            return int(s, 8)
        else:
            return int(s)
    except ValueError:
        pass

    # Try as comma-separated names
    total = 0
    for name in s.split(','):
        name = name.strip()
        if name in FLAG_NAME_TO_VAL:
            total |= FLAG_NAME_TO_VAL[name]
        else:
            raise ValueError(f"Unknown flag: {name}")
    return total

def flag_to_names(flag):
    """Convert flag value to comma-separated names."""
    names = []
    for val, name in FLAG_NAMES:
        if flag & val:
            names.append(name)
    return ','.join(names)

def cmd_flags(args):
    """samtools flags - explain BAM flags."""
    if not args:
        print_flags_help()
        return 0

    for arg in args:
        try:
            flag = parse_flag_value(arg)
        except ValueError as e:
            print(f"samtools flags: Could not parse \"{arg}\"", file=sys.stderr)
            print_flags_help()
            return 1

        names = flag_to_names(flag)
        print(f"0x{flag:x}\t{flag}\t{names}")

    return 0

def print_flags_help():
    print("""About: Convert between textual and numeric flag representation
Usage: samtools flags FLAGS...

Each FLAGS argument is either an INT (in decimal/hexadecimal/octal) representing
a combination of the following numeric flag values, or a comma-separated string
NAME,...,NAME representing a combination of the following flag names:

   0x1     1  PAIRED         paired-end / multiple-segment sequencing technology
   0x2     2  PROPER_PAIR    each segment properly aligned according to aligner
   0x4     4  UNMAP          segment unmapped
   0x8     8  MUNMAP         next segment in the template unmapped
  0x10    16  REVERSE        SEQ is reverse complemented
  0x20    32  MREVERSE       SEQ of next segment in template is rev.complemented
  0x40    64  READ1          the first segment in the template
  0x80   128  READ2          the last segment in the template
 0x100   256  SECONDARY      secondary alignment
 0x200   512  QCFAIL         not passing quality controls or other filters
 0x400  1024  DUP            PCR or optical duplicate
 0x800  2048  SUPPLEMENTARY  supplementary alignment""")

