def cmd_fastq(args):
    """samtools fastq - converts BAM to FASTQ."""
    return _cmd_fasta_fastq(args, fmt='fastq')

def _cmd_fasta_fastq(args, fmt='fasta'):
    bam_file = None
    output_file = None
    read1_file = None
    read2_file = None
    singleton_file = None
    flag_require = 0
    flag_exclude = 0x900  # default exclude secondary and supplementary
    append_rd_num = -1  # -1=auto, 0=no, 1=yes

    i = 0
    while i < len(args):
        a = args[i]
        if a in ('-o', '--output'):
            i += 1
            if i < len(args):
                output_file = args[i]
        elif a in ('-1',):
            i += 1
            if i < len(args):
                read1_file = args[i]
        elif a in ('-2',):
            i += 1
            if i < len(args):
                read2_file = args[i]
        elif a in ('-s',):
            i += 1
            if i < len(args):
                singleton_file = args[i]
        elif a in ('-f', '--require-flags'):
            i += 1
            if i < len(args):
                flag_require = parse_flag_value(args[i])
        elif a in ('-F', '--excl-flags', '--exclude-flags'):
            i += 1
            if i < len(args):
                flag_exclude = parse_flag_value(args[i])
        elif a in ('-@', '--threads', '-n', '-N'):
            if a in ('-@',):
                i += 1
        elif not a.startswith('-'):
            bam_file = a
        i += 1

    if bam_file is None:
        return 1

    out = open(output_file, 'w') if output_file else sys.stdout

    bf = BAMFile(bam_file)

    for rec in bf.records():
        if flag_require and (rec.flag & flag_require) != flag_require:
            continue
        if flag_exclude and (rec.flag & flag_exclude):
            continue

        name = rec.read_name
        # Add /1 or /2 suffix based on flags
        if rec.flag & FLAG_READ1:
            name = name + '/1'
        elif rec.flag & FLAG_READ2:
            name = name + '/2'

        seq = rec.seq if rec.seq else ''
        if rec.flag & FLAG_REVERSE:
            seq = reverse_complement(seq)

        if fmt == 'fasta':
            out.write(f">{name}\n")
            for j in range(0, len(seq), 60):
                out.write(seq[j:j+60] + '\n')
        else:  # fastq
            qual = rec.qual
            if rec.flag & FLAG_REVERSE and qual:
                qual = bytes(reversed(qual))
            qual_str = ''.join(chr(q + 33) for q in qual) if qual else ('I' * len(seq))
            out.write(f"@{name}\n{seq}\n+\n{qual_str}\n")

    bf.close()

    if output_file:
        out.close()

    return 0

def reverse_complement(seq):
    """Reverse complement a DNA sequence."""
    comp = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C', 'N': 'N',
            'a': 't', 't': 'a', 'c': 'g', 'g': 'c', 'n': 'n',
            'M': 'K', 'K': 'M', 'R': 'Y', 'Y': 'R', 'S': 'S',
            'W': 'W', 'B': 'V', 'V': 'B', 'D': 'H', 'H': 'D',
            '=': '=', 'X': 'X'}
    return ''.join(comp.get(c, 'N') for c in reversed(seq))

