        elif a in ('-Q', '--min-BQ'):
            i += 1
            if i < len(args):
                min_bq = int(args[i])
        elif a in ('-@', '--threads'):
            i += 1
        elif a in ('-v', '-u', '-g', '-B', '-E', '-I', '-A', '-R', '-x'):
            pass
        elif not a.startswith('-'):
            bam_files.append(a)
        i += 1

    if not bam_files:
        print("Usage: samtools mpileup [options] in1.bam [in2.bam [...]]", file=sys.stderr)
        return 1

    # For each BAM file, compute pileup
    for bam_file in bam_files:
        bf = BAMFile(bam_file)
        refs = bf.refs

        # Build position -> list of (base, qual, strand) 
        pileup = defaultdict(lambda: defaultdict(list))  # refID -> pos -> list

        for rec in bf.records():
            if rec.flag & FLAG_UNMAP:
                continue
            if rec.flag & FLAG_SECONDARY:
                continue
            if rec.mapq < min_mapq:
                continue
            if rec.refID < 0 or rec.pos < 0:
                continue

            seq = rec.seq
            qual = rec.qual
            pos = rec.pos
            qi = 0
            is_rev = bool(rec.flag & FLAG_REVERSE)

            for op_len, op_code in rec.cigar:
                if op_code in (0, 7, 8):  # M, =, X
                    for j in range(op_len):
                        if qi < len(seq):
                            bq = qual[qi] if qual and qi < len(qual) else 0
                            if bq >= min_bq:
                                base = seq[qi].upper()
                                if is_rev:
                                    base = base.lower()
                                pileup[rec.refID][pos + j].append((base, bq))
                        qi += 1
                    pos += op_len
                elif op_code == 2:  # D
                    pos += op_len
                elif op_code == 3:  # N
                    pos += op_len
                elif op_code == 1:  # I
                    qi += op_len
                elif op_code == 4:  # S
                    qi += op_len

        bf.close()

        # Print pileup
        for r_idx, (rname, rlen) in enumerate(refs):
            if r_idx not in pileup:
                continue
            for pos in sorted(pileup[r_idx].keys()):
                bases_quals = pileup[r_idx][pos]
                if not bases_quals:
                    continue
                if len(bases_quals) > max_depth:
                    bases_quals = bases_quals[:max_depth]
                bases = ''.join(b for b, q in bases_quals)
                quals = ''.join(chr(q + 33) for b, q in bases_quals)

                # Get ref base
                ref_base = 'N'

                print(f"{rname}\t{pos+1}\t{ref_base}\t{len(bases_quals)}\t{bases}\t{quals}")

    return 0

