            if i < len(args):
                min_mapq = int(args[i])
        elif a in ('-@', '--threads'):
            i += 1
        elif not a.startswith('-'):
            if bed_file is None:
                bed_file = a
            else:
                bam_files.append(a)
        i += 1

    if bed_file is None or not bam_files:
        print("Usage: samtools bedcov [options] <bed.file> <in1.bam> [...]", file=sys.stderr)
        return 1

    # Read BED regions
    regions = []
    with open(bed_file) as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            parts = line.split('\t')
            if len(parts) >= 3:
                chrom = parts[0]
                start = int(parts[1])
                end = int(parts[2])
                regions.append((chrom, start, end, line))

    for bam_file in bam_files:
        bf = BAMFile(bam_file)
        refs = bf.refs
        ref_idx = {n: i for i, (n, l) in enumerate(refs)}

        # Build depth for each needed region
        region_cov = {i: 0 for i in range(len(regions))}

        # Build per-ref depth arrays
        needed_refs = set()
        for chrom, start, end, _ in regions:
            if chrom in ref_idx:
                needed_refs.add(ref_idx[chrom])

        depths = {r: defaultdict(int) for r in needed_refs}

        for rec in bf.records():
            if rec.flag & FLAG_UNMAP:
                continue
            if rec.mapq < min_mapq:
                continue
            if rec.refID not in needed_refs:
                continue

            pos = rec.pos
            qi = 0

            for op_len, op_code in rec.cigar:
                if op_code in (0, 7, 8):  # M, =, X
                    for j in range(op_len):
                        depths[rec.refID][pos + j] += 1
                    pos += op_len
                    qi += op_len
                elif op_code == 2:  # D
                    pos += op_len
                elif op_code == 3:  # N
                    pos += op_len
                elif op_code == 1:  # I
                    qi += op_len
                elif op_code == 4:  # S
                    qi += op_len

        bf.close()

        for i, (chrom, start, end, orig_line) in enumerate(regions):
            cov = 0
            if chrom in ref_idx:
                r_idx = ref_idx[chrom]
                if r_idx in depths:
                    for p in range(start, end):
                        cov += depths[r_idx].get(p, 0)
            print(f"{orig_line}\t{cov}")

    return 0

