# PERFECT! When accounting for strand direction (reverse complement reads have reversed quality),
# the distributions MATCH exactly!

# So the fix for FFQ/LFQ: for reverse-strand reads, cycle 1 = last quality, etc.

cat > /tmp/fix_ffq.py << 'PYEOF'
with open('/workspace/samtools.py', 'r') as f:
    content = f.read()

# Fix the per-cycle quality computation
old_ffq = """        # Per-cycle quality
        if qual and seq_len > 0:
            for c, q in enumerate(qual):
                cycle = c + 1
                if is_r1 or not is_r2:
                    ffq[cycle][q] += 1
                else:
                    lfq[cycle][q] += 1"""

new_ffq = """        # Per-cycle quality - account for strand direction
        if qual and seq_len > 0:
            is_reverse = bool(flag & 0x10)  # FLAG_REVERSE
            for c, q in enumerate(qual):
                # For reverse strand, cycle 1 = last base = last quality value
                if is_reverse:
                    cycle = seq_len - c  # 1-indexed from end
                else:
                    cycle = c + 1  # 1-indexed from start
                if is_r1 or not is_r2:
                    ffq[cycle][q] += 1
                else:
                    lfq[cycle][q] += 1"""

if old_ffq in content:
    content = content.replace(old_ffq, new_ffq)
    print("Fixed FFQ/LFQ cycle computation")
else:
    print("Not found!")
    idx = content.find("# Per-cycle quality")
    print(repr(content[idx:idx+200]))

with open('/workspace/samtools.py', 'w') as f:
    f.write(content)
PYEOF
